// Extract and normalize SIEM alert fields
// Supports Wazuh and Splunk payloads

const payload = $input.first().json;
const raw = payload.raw_data || payload;

// Wazuh normalization
const srcIp = raw.data?.srcip || raw.agent?.ip || raw.src_ip || raw.source_ip || 'unknown';
const dstIp = raw.data?.dstip || raw.dst_ip || raw.destination_ip || 'unknown';
const username = raw.data?.dstuser || raw.user?.name || raw.username || raw.user || 'unknown';
const ruleId = raw.rule?.id || raw.rule_id || raw.EventID || 'unknown';
const ruleDesc = raw.rule?.description || raw.message || raw.msg || 'No description';
const ruleLevel = parseInt(raw.rule?.level || raw.severity_score || 5);
const agentName = raw.agent?.name || raw.hostname || raw.host || 'unknown';
const agentId = raw.agent?.id || raw.host_id || 'unknown';
const eventTime = raw.timestamp || raw['@timestamp'] || new Date().toISOString();

// Map Wazuh rule level (1-15) to severity
let severity = 'Low';
if (ruleLevel >= 13) severity = 'Critical';
else if (ruleLevel >= 10) severity = 'High';
else if (ruleLevel >= 7) severity = 'Medium';

return [{
  json: {
    _event_id: payload._constellation_event_id || `BT-${Date.now()}`,
    _received_at: new Date().toISOString(),
    // Alert fields
    rule_id: ruleId,
    rule_desc: ruleDesc,
    rule_level: ruleLevel,
    severity,
    src_ip: srcIp,
    dst_ip: dstIp,
    username,
    agent_name: agentName,
    agent_id: agentId,
    event_time: eventTime,
    // These will be populated by enrichment nodes
    geo_data: null,
    vt_score: null,
    asset_data: null,
    user_data: null,
    confidence_score: payload.confidence_score || 50,
    _raw: raw
  }
}];

// ─── CONFIDENCE SCORE ENGINE ──────────────────────────────────
// Combines GeoIP, VirusTotal, asset context, and rule severity
// to produce a final confidence score and triage decision.

const alert = $('Extract Alert Fields').first().json;
const geo = $('GeoIP Lookup').first().json;
const vt = $('VirusTotal IP Check').first().json;
const assets = $('CMDB Asset Lookup').all();

// ── GeoIP Signal ───────────────────────────────────────────────
const highRiskCountries = ['CN','RU','KP','IR','BY','CU','SY'];
const isHighRiskGeo = highRiskCountries.includes(geo.country_code);
const isVPN = geo.org?.toLowerCase().includes('vpn') ||
               geo.org?.toLowerCase().includes('hosting') ||
               geo.org?.toLowerCase().includes('proxy');
const geoRiskScore = isHighRiskGeo ? 85 : isVPN ? 70 : 40;

// ── VirusTotal Signal ──────────────────────────────────────────
const vtMalicious = vt.data?.attributes?.last_analysis_stats?.malicious || 0;
const vtTotal = Object.values(vt.data?.attributes?.last_analysis_stats || {}).reduce((a,b) => a+b, 0) || 1;
const vtScore = Math.round((vtMalicious / vtTotal) * 100);

// ── Asset Signal ──────────────────────────────────────────────
const asset = assets.length > 0 ? assets[0].json : null;
const assetCriticality = asset?.criticality || 'unknown';
const criticalityBoost = { critical: 20, high: 15, medium: 10, low: 5, unknown: 0 }[assetCriticality.toLowerCase()] || 0;

// ── Rule Level Signal ─────────────────────────────────────────
const ruleLevelScore = Math.min(100, (alert.rule_level / 15) * 100);

// ── Composite Confidence ──────────────────────────────────────
const confidence = Math.round(
  (geoRiskScore * 0.25) +
  (vtScore * 0.30) +
  (ruleLevelScore * 0.30) +
  (criticalityBoost * 0.15)
);

// ── Triage Decision ────────────────────────────────────────────
let decision = 'MANUAL_REVIEW';
let jiraAutoCreate = false;
if (confidence >= 90) { decision = 'AUTO_TICKET_CRITICAL'; jiraAutoCreate = true; }
else if (confidence >= 75) { decision = 'AUTO_TICKET'; jiraAutoCreate = true; }
else if (confidence >= 60) { decision = 'ASSISTED_TRIAGE'; }

return [{
  json: {
    ...alert,
    // Enrichment results
    geo_data: {
      country: geo.country_name,
      country_code: geo.country_code,
      city: geo.city,
      org: geo.org,
      is_vpn: isVPN,
      is_high_risk_geo: isHighRiskGeo
    },
    vt_score: vtScore,
    vt_malicious_count: vtMalicious,
    asset_data: asset,
    // Scoring
    confidence_score: confidence,
    confidence_breakdown: {
      geo_risk: geoRiskScore,
      virustotal: vtScore,
      rule_level: Math.round(ruleLevelScore),
      asset_criticality: criticalityBoost
    },
    triage_decision: decision,
    jira_auto_create: jiraAutoCreate,
    // Priority: CRITICAL if severity=Critical AND confidence≥75
    jira_priority: alert.severity === 'Critical' && confidence >= 75 ? 'Highest' :
                   alert.severity === 'High' ? 'High' :
                   alert.severity === 'Medium' ? 'Medium' : 'Low'
  }
}];

